        $c2 = comb($i, $k, $fact, $invFact, $mod);
        $sign = ($i - $k) % 2 == 0 ? 1 : ($mod - 1);
        // 2/((i+1)*(i+2))
        $denom = (($i + 1) * ($i + 2)) % $mod;
        $invDenom = modPow($denom, $mod - 2, $mod);
        $term = ($c1 * $c2 % $mod * $sign % $mod * 2 % $mod * $invDenom) % $mod;
        $sum = ($sum + $term) % $mod;
    }

    $result = ($l % $mod * $sum) % $mod;
    echo $result . "\n";
}

solve();
